-- Migrasi aditif awal. Jalankan pada database studio terpisah, setelah backup.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(id text PRIMARY KEY);
INSERT INTO roles(id) VALUES ('founder'),('administrator'),('chief_editor'),('editor'),('writer'),('illustrator'),('reviewer'),('reader') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS memberships(user_id uuid NOT NULL REFERENCES users(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), role_id text NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,workspace_id,role_id));
CREATE TABLE IF NOT EXISTS permissions(id text PRIMARY KEY);
CREATE TABLE IF NOT EXISTS role_permissions(role_id text REFERENCES roles(id), permission_id text REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS book_projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), title text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','planned','running','review','approved','published','failed')), created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS book_projects_workspace_idx ON book_projects(workspace_id,created_at DESC);
CREATE TABLE IF NOT EXISTS book_briefs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL UNIQUE REFERENCES book_projects(id) ON DELETE CASCADE, content jsonb NOT NULL, version int NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS book_outlines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), content jsonb NOT NULL, version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chapters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), title text NOT NULL, position int NOT NULL, status text NOT NULL DEFAULT 'draft', UNIQUE(project_id,position));
CREATE TABLE IF NOT EXISTS sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chapter_id uuid NOT NULL REFERENCES chapters(id), title text NOT NULL, position int NOT NULL, content text NOT NULL DEFAULT '', UNIQUE(chapter_id,position));
CREATE TABLE IF NOT EXISTS agents(id text PRIMARY KEY, name text NOT NULL, system_prompt_version text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS agent_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), agent_id text NOT NULL REFERENCES agents(id), idempotency_key text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','queued','running','waiting_approval','succeeded','failed','dead','cancelled')), input jsonb NOT NULL, output jsonb, attempts int NOT NULL DEFAULT 0, max_attempts int NOT NULL DEFAULT 3, checkpoint jsonb, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,idempotency_key));
CREATE INDEX IF NOT EXISTS agent_tasks_pending_idx ON agent_tasks(status,created_at);
CREATE TABLE IF NOT EXISTS agent_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES agent_tasks(id), attempt int NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text NOT NULL, error text, UNIQUE(task_id,attempt));
CREATE TABLE IF NOT EXISTS task_dependencies(task_id uuid NOT NULL REFERENCES agent_tasks(id), depends_on_id uuid NOT NULL REFERENCES agent_tasks(id), PRIMARY KEY(task_id,depends_on_id), CHECK(task_id <> depends_on_id));
CREATE TABLE IF NOT EXISTS storage_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), storage_key text NOT NULL UNIQUE, checksum_sha256 char(64) NOT NULL, media_type text NOT NULL, bytes bigint NOT NULL CHECK(bytes>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS document_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id), asset_id uuid NOT NULL REFERENCES storage_assets(id), version int NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,version));
CREATE TABLE IF NOT EXISTS illustrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), asset_id uuid REFERENCES storage_assets(id), brief text NOT NULL, status text NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS exercises(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chapter_id uuid NOT NULL REFERENCES chapters(id), content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS editorial_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), reviewer_id uuid REFERENCES users(id), decision text NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quality_checks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), check_name text NOT NULL, passed boolean NOT NULL, evidence jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), approved_by uuid NOT NULL REFERENCES users(id), scope text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS export_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), format text NOT NULL, status text NOT NULL DEFAULT 'pending', asset_id uuid REFERENCES storage_assets(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_providers(id text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS ai_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES book_projects(id), task_id uuid REFERENCES agent_tasks(id), provider_id text NOT NULL REFERENCES ai_providers(id), model text NOT NULL, input_tokens int NOT NULL DEFAULT 0, output_tokens int NOT NULL DEFAULT 0, cost_usd numeric(14,6), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ai_usage_project_idx ON ai_usage(project_id,created_at);
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES workspaces(id), actor_id uuid REFERENCES users(id), action text NOT NULL, target_type text NOT NULL, target_id text, metadata jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_logs_workspace_idx ON audit_logs(workspace_id,created_at DESC);
